-- 阶段5：招生内容与AI建议/配额；0001–0021原样保留。
CREATE TABLE content_items(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,type TEXT NOT NULL,subject TEXT NOT NULL,scene TEXT,title TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','ready','copied','published')),doc_json TEXT NOT NULL CHECK(json_valid(doc_json)),manifest_json TEXT NOT NULL CHECK(json_valid(manifest_json)),author_id TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id));
